      "id": "m-john-harrison-booker-prize-win",
      "title": "M John Harrison Breaks the Booker Prize Boundary for Science Fiction",
      "kicker": "CULTURE // NEWS",
      "category": "culture",
      "subtopic": "news",
      "author": "Claire Sterling",
      "role": "Staff Writer",
